query QueryEntryInstance($entry_id: String!){
    entry(
        entry_id:$entry_id
    ){
        polymer_entities {
            polymer_entity_instances{
                rcsb_id
                polymer_entity{
                    rcsb_polymer_entity{
                        pdbx_description
                        rcsb_polymer_name_combined{
                            names
                        }
                        formula_weight
                    }
                    entity_poly{
                        rcsb_entity_polymer_type
                        rcsb_sample_sequence_length
                    }
                    rcsb_entity_source_organism {
                        ncbi_scientific_name
                    }
                    entry {
                        rcsb_entry_info{
                            experimental_method
                            resolution_combined
                            molecular_weight
                            structure_determination_methodology
                            representative_model
                        }
                    }
                }
                rcsb_polymer_entity_instance_container_identifiers{
                    asym_id
                    auth_asym_id
                    entry_id
                    entity_id
                    auth_to_entity_poly_seq_mapping
                }
            }
        }
        assemblies {
            rcsb_assembly_container_identifiers {
                assembly_id
            }
            pdbx_struct_assembly_gen {
                assembly_id
                asym_id_list
                oper_expression
            }
        }
    }
}

query QueryMultipleEntityInstances($entity_ids: [String!]!){
    polymer_entities(
        entity_ids:$entity_ids
    ){
        polymer_entity_instances{
            rcsb_id
            polymer_entity{
                rcsb_polymer_entity{
                    pdbx_description
                    rcsb_polymer_name_combined{
                        names
                    }
                    formula_weight
                }
                entity_poly{
                    rcsb_entity_polymer_type
                    rcsb_sample_sequence_length
                }
                rcsb_entity_source_organism {
                    ncbi_scientific_name
                }
                entry {
                    rcsb_entry_info{
                        representative_model
                        experimental_method
                        resolution_combined
                        structure_determination_methodology
                    }
                }
            }
            rcsb_polymer_entity_instance_container_identifiers{
                asym_id
                auth_asym_id
                entry_id
                entity_id
                auth_to_entity_poly_seq_mapping
            }
        }
    }
}

query QueryAlignment($queryId: String!, $from: SequenceReference!, $to:SequenceReference!, $range:[Int!]){
    alignments(
        queryId:$queryId
        from:$from
        to:$to
        range:$range
    ){
        query_sequence
        target_alignments {
            target_id
            orientation
            target_sequence
            coverage {
                query_coverage
                query_length
                target_coverage
                target_length
            }
            aligned_regions {
                query_begin
                query_end
                target_begin
                target_end
                exon_shift
            }
        }

    }
}

