query GetPublicServiceImplementationsPaginated($searchTerms: [String], $where: ServiceImplementationFilterInput!, $pageSize: Int!, $after: Int, $orderBy: [OrderByInput]) {
  serviceImplementation {
    allServiceImplementationsPaginated(
      skip: $after
      take: $pageSize
      where: $where
      searchTerms: $searchTerms
      orderBy: $orderBy
    ) {
      pageInfo {
        hasNextPage
        hasPreviousPage
      }
      totalCount
      items {
        token
        modified
        names {
          language
          value
        }
        code
        capacity
        status
        area {
          municipalities {
            code
            names {
              language
              value
            }
          }
        }
        nonStop
        startDate
        endDate
        publicationStartDate
        publicationEndDate
        implementationDurationDescription {
          language
          value
        }
        implementationType
        languages {
          languageCode
        }
        registrationWebPages {
          language
          value
          url
        }
        addressInfo {
          value
          language
        }
        serviceOffering {
          token
          organizations {
            roleType
            organization {
              token
              names {
                language
                value
              }
            }
          }
          service {
            token
            names {
              language
              value
            }
            category {
              code
            }
          }
        }
      }
    }
  }
}

