      additionalInformation {
        language
        value
      }
      addressInfo {
        language
        value
      }
      area {
        municipalities {
          code
          names {
            language
            value
          }
        }
      }
      serviceOffering {
        token
        startDate
        endDate
        organizations {
          provisionType
          roleType
