query GetPublicService($token: Uuid!) {
  service {
    services(where: {or: [{ptvToken: {eq: $token}}, {token: {eq: $token}}]}) {
      token
      ptvToken
      courseNumber
      category {
        code
        parentCode
        name {
          language
          value
        }
      }
      type
      status
      modified
      origin
      publicationStartDate
      publicationEndDate
      responsibleOrganization {
        token
        names {
          language
          value
          type
        }
      }
      names {
        language
        value
        type
      }
      languages {
        languageCode
      }
      areaType
      chargeType
      description {
        language
        value
      }
      userInstruction {
        language
        value
      }
      requirements {
        language
        value
      }
      summary {
        language
        value
      }
      targetGroups {
        targetGroupCode
      }
      serviceOfferings {
        token
        serviceImplementations {
          token
        }
      }
    }
  }
}

query GetCategories($language: String!) {
  ontology {
    serviceCategories {
      ...Categories
    }
  }
}

fragment Categories on ServiceCategory {
  allowedForServiceTypes
  code
  name(language: $language) {
    language
    value
  }
  parentCode
  appropriation
  atmtEditable
  startDate
  endDate
}
